"use client";
import {FormEvent,useState} from "react";import {useRouter} from "next/navigation";import {api} from "@/lib/api";
export default function Home(){const router=useRouter();const[mode,setMode]=useState<"login"|"register">("register");const[error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setError("");const f=new FormData(e.currentTarget);try{const body=mode==="register"?{name:f.get("name"),email:f.get("email"),password:f.get("password"),role:f.get("role")}:{email:f.get("email"),password:f.get("password")};const r=await api<{access_token:string,user:{role:string}}>(`/api/auth/${mode}`,{method:"POST",body:JSON.stringify(body)});localStorage.setItem("venv_token",r.access_token);router.push(r.user.role==="recruiter"?"/company":"/intake")}catch(x){setError(x instanceof Error?x.message:"حدث خطأ")}}return <main className="auth"><section className="auth-art"><div className="brand"><span className="brandmark">V</span> Venv</div><h1 className="title" style={{marginTop:100}}>جرّب أول يوم عمل<br/>قبل أن تبدأه.</h1><p className="subtitle" style={{color:"#b9cfca"}}>فضاء عمل يجمعك بمدير ومرشد وموارد بشرية من الذكاء الاصطناعي، ويتطور مع كل مهمة.</p></section><section className="auth-form"><form className="form" onSubmit={submit}><span className="eyebrow">ابدأ رحلتك</span><h2>{mode==="register"?"إنشاء حساب":"تسجيل الدخول"}</h2>{mode==="register"&&<><label>الاسم</label><input name="name" required/><label>نوع الحساب</label><select name="role"><option value="learner">طالب أو حديث تخرج</option><option value="recruiter">مسؤول توظيف</option></select></>}<label>البريد الإلكتروني</label><input name="email" type="email" required/><label>كلمة المرور</label><input name="password" type="password" minLength={8} required/>{error&&<p className="error">{error}</p>}<button className="btn">{mode==="register"?"إنشاء الحساب":"دخول"}</button><button type="button" className="btn secondary" onClick={()=>setMode(mode==="register"?"login":"register")}>{mode==="register"?"لدي حساب":"إنشاء حساب جديد"}</button></form></section></main>}
